package local.guide.client;
import android.app.*; import android.os.*; import android.net.Uri; import android.view.*; import android.webkit.*; import android.widget.*;
import androidx.media3.common.MediaItem; import androidx.media3.common.Player; import androidx.media3.common.PlaybackException; import androidx.media3.exoplayer.ExoPlayer; import androidx.media3.ui.PlayerView; import androidx.media3.datasource.DefaultHttpDataSource; import androidx.media3.exoplayer.source.DefaultMediaSourceFactory;
import java.util.HashMap;
public class MainActivity extends Activity {
 private WebView web; private FrameLayout root; private View full; private WebChromeClient.CustomViewCallback callback; private String origin; private ExoPlayer player; private PlayerView nativeView; private final Handler handler=new Handler(Looper.getMainLooper());
 private int port(Uri a){return a.getPort()!=-1?a.getPort():"https".equals(a.getScheme())?443:80;}
 private boolean same(String url){try{Uri a=Uri.parse(url),b=Uri.parse(origin);return a.getHost()!=null&&a.getHost().equalsIgnoreCase(b.getHost())&&a.getScheme().equals(b.getScheme())&&port(a)==port(b);}catch(Exception e){return false;}}
 @Override public void onCreate(Bundle b){super.onCreate(b);origin=getPreferences(0).getString("origin","http://192.168.1.15:9191");root=new FrameLayout(this);setContentView(root);web=new WebView(this);root.addView(web,new FrameLayout.LayoutParams(-1,-1));WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setMediaPlaybackRequiresUserGesture(false);s.setAllowFileAccess(false);s.setAllowContentAccess(false);CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);
 web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){String u=r.getUrl().toString();if(!r.isForMainFrame())return false;if(!same(u))return true;if(r.hasGesture()&&stream(u)){play(u);return true;}return false;}@Override public void onPageFinished(WebView v,String url){if(same(url))adapt();CookieManager.getInstance().flush();}});
 web.setWebChromeClient(new WebChromeClient(){@Override public void onShowCustomView(View v,CustomViewCallback cb){if(full!=null||player!=null){cb.onCustomViewHidden();return;}full=v;callback=cb;root.addView(v,new FrameLayout.LayoutParams(-1,-1));web.setVisibility(View.INVISIBLE);immersive();}@Override public void onHideCustomView(){closeFull();}});
 web.loadUrl(origin+"/guide");immersive();if(!getPreferences(0).contains("origin"))settings();handler.post(tick);}
 private boolean stream(String u){String p=Uri.parse(u).getPath();return p!=null&&(p.startsWith("/proxy/ts/stream/")||p.endsWith(".m3u8")||p.endsWith(".ts"));}
 private final Runnable tick=new Runnable(){public void run(){if(web!=null&&full==null&&player==null&&same(web.getUrl()))adapt();handler.postDelayed(this,1000);}};
 private void adapt(){web.evaluateJavascript("(function(){if(location.pathname==='/'||location.pathname==='/dashboard'){location.replace('/guide');return;}if(window.__guideClient)return;window.__guideClient=true;document.addEventListener('playing',function(e){var v=e.target;if(v.tagName==='VIDEO'&&location.pathname.startsWith('/guide')&&!document.fullscreenElement&&v.requestFullscreen){try{v.requestFullscreen().catch(function(){});}catch(e){}}},true);document.addEventListener('keydown',function(e){if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)||document.fullscreenElement)return;var a=document.activeElement,r=a.getBoundingClientRect(),x=r.x+r.width/2,y=r.y+r.height/2,best=null,score=Infinity;document.querySelectorAll('button,a[href],[role=button],[tabindex],[onclick]').forEach(function(n){if(n===a||n.disabled||!n.getClientRects().length)return;var q=n.getBoundingClientRect(),dx=q.x+q.width/2-x,dy=q.y+q.height/2-y,p=e.key==='ArrowRight'?dx:e.key==='ArrowLeft'?-dx:e.key==='ArrowDown'?dy:-dy,c=e.key==='ArrowRight'||e.key==='ArrowLeft'?dy:dx;if(p>0&&p+Math.abs(c)*3<score){score=p+Math.abs(c)*3;best=n;}});if(best){e.preventDefault();best.focus();best.scrollIntoView({block:'nearest',inline:'nearest'});}},true);})()",null);}
 private void play(String url){if(!same(url)||!stream(url)||player!=null)return;HashMap<String,String> headers=new HashMap<>();String cookie=CookieManager.getInstance().getCookie(url);if(cookie!=null)headers.put("Cookie",cookie);DefaultHttpDataSource.Factory http=new DefaultHttpDataSource.Factory().setDefaultRequestProperties(headers);player=new ExoPlayer.Builder(this).setMediaSourceFactory(new DefaultMediaSourceFactory(this).setDataSourceFactory(http)).build();nativeView=new PlayerView(this);nativeView.setPlayer(player);root.addView(nativeView,new FrameLayout.LayoutParams(-1,-1));web.setVisibility(View.INVISIBLE);nativeView.requestFocus();player.addListener(new Player.Listener(){@Override public void onPlayerError(PlaybackException e){Toast.makeText(MainActivity.this,"Playback failed: "+e.getErrorCodeName(),Toast.LENGTH_LONG).show();closePlayer();}});player.setMediaItem(MediaItem.fromUri(url));player.prepare();player.play();immersive();}
 private void closePlayer(){if(player==null)return;nativeView.setPlayer(null);player.release();player=null;root.removeView(nativeView);nativeView=null;web.setVisibility(View.VISIBLE);web.requestFocus();immersive();}
 private void immersive(){getWindow().getDecorView().setSystemUiVisibility(5894);}
 private void closeFull(){if(full==null)return;root.removeView(full);full=null;web.setVisibility(View.VISIBLE);if(callback!=null){callback.onCustomViewHidden();callback=null;}immersive();}
 private void settings(){EditText input=new EditText(this);input.setSingleLine();input.setText(origin);new AlertDialog.Builder(this).setTitle("Server address").setView(input).setNegativeButton("Cancel",null).setPositiveButton("Connect",(d,w)->{Uri u=Uri.parse(input.getText().toString().trim());if(u.getHost()==null||!("http".equals(u.getScheme())||"https".equals(u.getScheme()))||u.getUserInfo()!=null){Toast.makeText(this,"Invalid server URL",Toast.LENGTH_LONG).show();return;}origin=u.getScheme()+"://"+u.getEncodedAuthority();getPreferences(0).edit().putString("origin",origin).apply();web.loadUrl(origin+"/guide");}).show();}
 @Override public boolean onKeyDown(int key,KeyEvent e){if(key==KeyEvent.KEYCODE_MENU&&player==null&&full==null){settings();return true;}return super.onKeyDown(key,e);}
 @Override public void onBackPressed(){if(player!=null)closePlayer();else if(full!=null){closeFull();web.evaluateJavascript("document.querySelectorAll('video').forEach(v=>v.pause());",null);}else if(web.canGoBack())web.goBack();else super.onBackPressed();}
 @Override protected void onPause(){super.onPause();if(player!=null)player.pause();web.onPause();CookieManager.getInstance().flush();}
 @Override protected void onResume(){super.onResume();if(web!=null)web.onResume();immersive();}
 @Override protected void onDestroy(){handler.removeCallbacks(tick);closePlayer();closeFull();web.destroy();super.onDestroy();}
}